      "content": "<p>The Tsardom of Russia emerged in the 16th century, expanding massively to become the Russian Empire. The 1917 Russian Revolution led to the establishment of the Soviet Union (USSR).</p><p>The USSR was a global superpower during the Cold War. Following its collapse in 1991, the Russian Federation emerged as the primary successor state.</p>",
