      "content": "<p>Russia is the largest country in the world by area, spanning 11 time zones across Eastern Europe and Northern Asia.</p><p>It features diverse landscapes including the vast Siberian tundra, deep forests (taiga), the Ural Mountains, and Lake Baikal, the world's deepest freshwater lake.</p>"
