      "content": "<p>China is one of the world's oldest continuous civilizations, ruled by successive dynasties for millennia. It made pivotal early inventions like papermaking and gunpowder.</p><p>The 20th century saw the fall of the last dynasty, decades of civil war, and the establishment of the People's Republic in 1949 under the Communist Party.</p>",
