      "content": "<p>China is the world's second-largest economy and a global manufacturing and technology powerhouse, having lifted hundreds of millions out of poverty since 1978.</p><p>It faces current challenges like an aging population due to past demographic policies, environmental degradation, and geopolitical tensions regarding trade and territory.</p>"
