      "content": "<p>China's vast geography includes the high Tibetan Plateau and Himalayan mountains to the west, and expansive plains and major river systems (Yangtze, Yellow) to the east.</p><p>The topography generally descends from the mountainous west to the populated coastal east, creating varied regional climates and landscapes.</p>"
