      "currency": "Renminbi (CNY)",
      "content": "<p>Chinese culture is profoundly influenced by Confucianism, emphasizing harmony, respect for elders, and education. It has a rich tradition in martial arts, calligraphy, and ceramics.</p><p>Traditional festivals like the Lunar New Year are central to cultural life. Chinese cuisine is incredibly diverse, with eight major regional culinary traditions.</p>",
