      "content": "<p>Home to the ancient Indus Valley Civilization, India has been a center of trade, culture, and major empires (Maurya, Gupta, Mughal) for millennia.</p><p>Following centuries of British colonial rule, India achieved independence in 1947 through a largely nonviolent movement led by Mahatma Gandhi, but also endured the traumatic Partition.</p>",
