      "content": "<p>India is the world's most populous country and a rapidly growing major economy, strong in IT services, pharmaceuticals, and agriculture.</p><p>While experiencing significant technological and economic advancement, it continues to grapple with severe poverty, infrastructural challenges, and deep socio-economic inequalities.</p>"
