      "content": "<p>India is incredibly diverse, being the birthplace of Hinduism, Buddhism, Jainism, and Sikhism. Its culture is a vibrant tapestry of languages, religions, and traditions.</p><p>It is globally famous for its cinema (Bollywood), classical dances, complex cuisine featuring rich spices, and deeply spiritual festivals like Diwali and Holi.</p>",
