      "currency": "Japanese Yen (JPY)",
      "content": "<p>Japanese culture uniquely blends deep-rooted traditions (Shinto shrines, tea ceremonies) with cutting-edge modern pop culture (anime, manga, video games).</p><p>The culture highly values harmony, respect, and meticulous craftsmanship. Japanese cuisine, notably sushi and ramen, is celebrated worldwide for its quality and aesthetics.</p>",
