      "content": "<p>The Korean peninsula has a rich history spanning dynasties like Joseon. Following Japanese annexation (1910-1945), the peninsula was divided into North and South.</p><p>The devastating Korean War (1950-1953) ended in an armistice. South Korea subsequently experienced the \"Miracle on the Han River\", transforming from poverty into a high-tech democracy.</p>",
