      "content": "<p>South Korea boasts a highly advanced, export-driven economy dominated by large conglomerates (chaebols) like Samsung and Hyundai. It leads in semiconductor and electronics manufacturing.</p><p>Despite its wealth, it faces critical demographic issues, holding the world's lowest fertility rate, alongside intense societal pressure in education and the workplace.</p>"
