      "content": "<p>South Korea has exploded in global cultural influence through the \"Korean Wave\" (Hallyu), exporting K-pop music, K-dramas, and cinema internationally.</p><p>The culture is deeply influenced by Confucian values, emphasizing respect for authority and family. Korean cuisine, famous for kimchi and barbecue, is highly popular.</p>",
