      "content": "<p>Australia is the world's smallest continent and sixth-largest country. Landscapes range from the dry \"Outback\" interior to tropical rainforests and the Great Dividing Range.</p><p>It features unique endemic wildlife like kangaroos, koalas, and wombats, alongside the Great Barrier Reef, the world's largest coral reef system.</p>"
