      "content": "<p>Ancient Egypt is one of history's earliest and greatest civilizations, famous for its pharaohs, pyramids, and hieroglyphs. It later fell under Greek, Roman, and Islamic rule.</p><p>Modern Egypt gained independence from British influence in the 20th century, becoming a republic in 1953 and playing a central role in Middle Eastern politics.</p>",
