      "content": "<p>Egyptian culture is a rich amalgamation of Pharaonic, Christian (Coptic), and Islamic heritage. It has long been the cultural and media heart of the Arab world.</p><p>Its historic monuments draw millions of tourists. Literature, cinema, and music from Egypt hold immense influence across the Middle East and North Africa.</p>",
