      "content": "<p>Inhabited originally by San and Khoekhoe peoples, European settlement began with the Dutch in 1652, followed by the British. The 20th century was dominated by the oppressive Apartheid system.</p><p>Apartheid ended after a long struggle, culminating in the first multiracial democratic elections in 1994, which saw Nelson Mandela elected as president.</p>",
