      "content": "<p>Nigeria was home to numerous ancient and historical states before British colonial rule united the diverse region in the late 19th and early 20th centuries.</p><p>It gained independence in 1960. Its modern history has been marked by a devastating civil war (Biafra), periods of military rule, and a return to democracy in 1999.</p>",
