      "content": "<p>Nigeria features diverse geography, with mangrove swamps in the coastal south, tropical rainforests inland, and savannas merging into the Sahel near the Sahara in the north.</p><p>The Niger River, after which the country is named, is a vital lifeline flowing through the country to the Gulf of Guinea.</p>"
