      "content": "<p>Saudi Arabia is the largest economy in the Middle East, traditionally reliant almost entirely on petroleum exports and state-owned Saudi Aramco.</p><p>Under the \"Vision 2030\" initiative, the country is aggressively attempting to diversify its economy, develop tourism, and enact social reforms.</p>"
