      "content": "<p>Occupying the vast majority of the Arabian Peninsula, Saudi Arabia's geography is defined by the harsh, expansive Arabian Desert, including the Rub' al Khali (Empty Quarter).</p><p>It is bordered by the Red Sea to the west and the Persian Gulf to the east, possessing no permanent rivers or lakes.</p>"
