      "content": "<p>Saudi culture is deeply rooted in Islamic teachings and Bedouin traditions. It hosts the two holiest cities in Islam, Mecca and Medina, drawing millions for the Hajj pilgrimage.</p><p>Historically conservative, the culture is currently undergoing rapid state-driven modernization, impacting entertainment, tourism, and women's rights.</p>",
