      "content": "<p>Turkey is a transcontinental country, largely situated on the Anatolian peninsula in Western Asia, with a small portion (East Thrace) in Southeast Europe.</p><p>It features high central plateaus, coastal plains, and controls the vital Bosporus and Dardanelles straits linking the Black and Mediterranean seas.</p>"
