      "content": "<p>Iraq's economy is heavily anchored by its massive petroleum reserves, ranking among the top producers within OPEC and generating over 90% of government revenue.</p><p>The nation is focused on rebuilding infrastructure, expanding power generation, restoring agricultural lands along river basins, and modernizing state institutions.</p>"
