  "Finland": {
    "flag": "🇫🇮",
    "region": "Northern Europe",
    "coordinates": {
      "lat": 60.1699,
      "lng": 24.9384
    },
    "history": {
      "title": "Historical Overview",
      "content": "<p>Finland was part of the Kingdom of Sweden for nearly 700 years until 1809, when it became an autonomous Grand Duchy within the Russian Empire. Following the Russian Revolution, Finland declared independence on December 6, 1917.</p><p>Finland defended its independence during World War II in the Winter War and Continuation War. During the post-war era, it pursued active neutrality, rapid industrialization, and built an advanced welfare state.</p>",
      "timeline": [
        {
          "year": "1809",
          "event": "Finland ceded by Sweden to Russia as Grand Duchy."
        },
        {
          "year": "1917",
          "event": "Declaration of Independence from Russia."
        },
        {
          "year": "1939-1940",
          "event": "Winter War fought against Soviet invasion."
        },
        {
          "year": "1995",
          "event": "Finland joins the European Union."
        },
        {
          "year": "2023",
          "event": "Finland officially joins NATO."
        }
      ]
    },
    "demographics": {
      "stats": {
        "population": "5.6 million",
        "gdp": "$300 billion",
        "capital": "Helsinki",
        "government": "Unitary Parliamentary Republic"
      },
      "content": "<p>Finland consistently ranks as the world's happiest country according to the UN World Happiness Report, driven by high social trust, world-class education, low corruption, and personal freedom.</p><p>The economy is driven by high-tech manufacturing, software development, paper/forestry products, and telecommunications pioneer Nokia.</p>"
    },
    "geography": {
      "stats": {
        "area": "338,455 km²",
        "continent": "Europe",
        "climate": "Cold temperate / subarctic",
        "borders": "Sweden, Norway, Russia"
      },
      "content": "<p>Known as the \"Land of a Thousand Lakes,\" Finland contains over 187,000 lakes and vast taiga forests covering nearly 75% of the country.</p><p>Finnish Lapland in the far north experiences the Midnight Sun during summer and northern lights (Aurora Borealis) during winter.</p>"
    },
    "culture": {
      "languages": [
        "Finnish",
        "Swedish"
      ],
      "currency": "Euro (EUR)",
      "content": "<p>Sauna culture is central to Finnish lifestyle, with over 3 million saunas across the nation. Concept of \"sisu\" embodies national stoic resilience and determination.</p><p>Finland has produced world-renowned classical composer Jean Sibelius, architect Alvar Aalto, and iconic Moomin stories created by Tove Jansson.</p>",
      "highlights": [
        "Helsinki Cathedral",
        "Santa Claus Village Rovaniemi",
        "Suomenlinna Fortress",
        "Archipelago Sea",
        "Lake Saimaa"
      ]
    }
  },
