  "Iceland": {
    "flag": "🇮🇸",
    "region": "Northern Europe",
    "coordinates": {
      "lat": 64.1466,
      "lng": -21.9426
    },
    "history": {
      "title": "Historical Overview",
      "content": "<p>Iceland was settled in the late 9th century, primarily by Norse Vikings and Celtic inhabitants. In 930 AD, settlers established the Althing, widely considered the world's oldest surviving parliamentary assembly.</p><p>Iceland entered unions with Norway (1262) and later Denmark under the Kalmar Union. It achieved full independence from Denmark on June 17, 1944, transforming from a fishing nation into a high-tech green energy economy.</p>",
      "timeline": [
        {
          "year": "874",
          "event": "Norse chieftain Ingólfur Arnarson establishes first permanent settlement."
        },
        {
          "year": "930",
          "event": "Althing parliament founded at Þingvellir."
        },
        {
          "year": "1262",
          "event": "Old Covenant merges Iceland with Norway."
        },
        {
          "year": "1944",
          "event": "Republic of Iceland formally declared at Þingvellir."
        },
        {
          "year": "2010",
          "event": "Eyjafjallajökull volcanic eruption disrupts transatlantic flights."
        }
      ]
    },
    "demographics": {
      "stats": {
        "population": "390,000",
        "gdp": "$30 billion",
        "capital": "Reykjavík",
        "government": "Unitary Parliamentary Republic"
      },
      "content": "<p>Iceland boasts one of the world's highest GDP per capita levels and quality of life rankings, powered by 100% renewable geothermal and hydroelectric energy, sustainable fisheries, and eco-tourism.</p><p>It ranks at the top of international indices for gender equality, safety, freedom of speech, and social cohesion.</p>"
    },
    "geography": {
      "stats": {
        "area": "103,000 km²",
        "continent": "Europe",
        "climate": "Subpolar oceanic",
        "borders": "None (Island nation in North Atlantic)"
      },
      "content": "<p>Straddling the Mid-Atlantic Ridge between North America and Europe, Iceland is a dramatic volcanic island characterized by active geysers, hot springs, black sand beaches, and massive glaciers like Vatnajökull.</p><p>Its unique geological active wilderness includes cascading waterfalls such as Gullfoss and volcanic craters along the Golden Circle.</p>"
    },
    "culture": {
      "languages": [
        "Icelandic"
      ],
      "currency": "Icelandic Króna (ISK)",
      "content": "<p>Icelandic culture is rooted in the medieval Icelandic Sagas, epic prose narratives chronicling Viking history and mythology preserved in pristine form due to the language's stability over a millennium.</p><p>Modern Iceland is renowned for creative arts, producing global music innovators like Björk and Sigur Rós, and a passionate reading culture (\"Jólabókaflóð\").</p>",
      "highlights": [
        "Blue Lagoon",
        "Golden Circle (Gullfoss & Geysir)",
        "Vatnajökull National Park",
        "Reynisfjara Black Sand Beach",
        "Harpa Concert Hall"
      ]
    }
  },
  "Luxembourg": {
    "flag": "🇱🇺",
    "region": "Western Europe",
    "coordinates": {
      "lat": 49.6116,
      "lng": 6.1319
    },
    "history": {
      "title": "Historical Overview",
      "content": "<p>Luxembourg's history began in 963 AD when Count Siegfried acquired the rocky promontory of Lucilinburhuc. Positioned strategically in Western Europe, its fortress grew into one of Europe's formidable strongholds, earning the title \"Gibraltar of the North.\"</p><p>Recognized as a sovereign Grand Duchy by the Treaty of London in 1867, Luxembourg became a founding member of the European Union, NATO, and the Benelux union in the 20th century.</p>",
      "timeline": [
        {
          "year": "963",
          "event": "Count Siegfried acquires Lucilinburhuc castle site."
        },
        {
          "year": "1867",
          "event": "Treaty of London guarantees Luxembourg's full independence and neutrality."
        },
        {
          "year": "1951",
          "event": "Founding member of European Coal and Steel Community."
        },
        {
          "year": "1995",
          "event": "Luxembourg City named European Capital of Culture."
        },
        {
          "year": "2020",
          "event": "Luxembourg becomes first country to offer nationwide free public transit."
        }
      ]
    },
    "demographics": {
      "stats": {
        "population": "660,000",
        "gdp": "$86 billion",
        "capital": "Luxembourg City",
        "government": "Unitary Parliamentary Constitutional Monarchy"
      },
      "content": "<p>Luxembourg has one of the world's highest GDP per capita rates, driven by a world-leading global private banking, investment fund, and financial services sector, alongside satellite technology (SES).</p><p>It is a cosmopolitan nation where nearly half of the resident population consists of foreign nationals, attracting over 200,000 cross-border commuters daily from France, Germany, and Belgium.</p>"
    },
    "geography": {
      "stats": {
        "area": "2,586 km²",
        "continent": "Europe",
        "climate": "Modified continental",
        "borders": "Belgium, France, Germany"
      },
      "content": "<p>Luxembourg is one of Europe's smallest nations, divided into the forested, hilly Éislek region in the north (part of the Ardennes) and the rolling agricultural Gutland region in the south.</p><p>The capital features dramatic deep sandstone gorges carved by the Alzette and Pétrusse rivers, spanned by historic stone viaducts.</p>"
    },
    "culture": {
      "languages": [
        "Luxembourgish",
        "French",
        "German"
      ],
      "currency": "Euro (EUR)",
      "content": "<p>Luxembourg enjoys a multilingual cultural heritage with trilingual education across French, German, and national language Luxembourgish (\"Lëtzebuergesch\").</p><p>The capital hosts major EU judicial and financial institutions, alongside UNESCO World Heritage ancient fortifications and scenic Moselle wine valley vineyards.</p>",
      "highlights": [
        "Bock Casemates",
        "Grand Ducal Palace",
        "Vianden Castle",
        "Müllerthal Region (Little Switzerland)",
        "Mudam Modern Art Museum"
      ]
    }
  },
