  "New Caledonia": {
    "flag": "🇳🇨",
    "region": "Oceania",
    "coordinates": {
      "lat": -20.9043,
      "lng": 165.618
    },
    "history": {
      "title": "Historical Overview",
      "content": "<p>New Caledonia was settled by Lapita Melanesian navigators around 1600 BC. British navigator Captain James Cook sighted the main island in 1774, naming it New Caledonia due to its resemblance to the Scottish Highlands.</p><p>France formally annexed the territory in 1853 under Napoleon III, establishing a penal colony until 1897. The 1998 Nouméa Accord granted gradual political autonomy and increased indigenous Kanak representation.</p>",
      "timeline": [
        {
          "year": "1600 BC",
          "event": "First Lapita settlers arrive in New Caledonia."
        },
        {
          "year": "1774",
          "event": "Captain James Cook names the main island New Caledonia."
        },
        {
          "year": "1853",
          "event": "France formally annexes the territory."
        },
        {
          "year": "1998",
          "event": "Nouméa Accord signed, establishing self-governing autonomy."
        },
        {
          "year": "2018-2021",
          "event": "Independence referendums held under the Nouméa Accord."
        }
      ]
    },
    "demographics": {
      "stats": {
        "population": "270,000",
        "gdp": "$9.5 billion",
        "capital": "Nouméa",
        "government": "Special Overseas Collectivity of France"
      },
      "content": "<p>New Caledonia holds approximately 20-30% of the world's proven nickel reserves, making metallurgy and nickel mining the backbone of the economy alongside French financial transfers and marine eco-tourism.</p>"
    },
    "geography": {
      "stats": {
        "area": "18,576 km²",
        "continent": "Oceania",
        "climate": "Tropical semi-humid",
        "borders": "None (Melanesian Archipelago)"
      },
      "content": "<p>Comprises the main island of Grande Terre, the Loyalty Islands, and Belep archipelago. The New Caledonia Lagoon is the world's second-largest double barrier reef and a UNESCO World Heritage site.</p>"
    },
    "culture": {
      "languages": [
        "French",
        "Kanak languages (30+ dialects)"
      ],
      "currency": "CFP Franc (XPF)",
      "content": "<p>Blends indigenous Kanak Melanesian traditions (Grand Case wooden architecture, Pilou ceremonial dance) with French Riviera gastronomy and lifestyle.</p>",
      "highlights": [
        "Nouméa Lagoon UNESCO Reef",
        "Heart of Voh Mangrove",
        "Tjibaou Cultural Centre",
        "Isle of Pines (Île des Pins)",
        "Ouvéa Atoll"
      ]
    }
  },
