  "Czech Rep.": {
    "flag": "🇨🇿",
    "region": "Central Europe",
    "coordinates": {
      "lat": 50.0755,
      "lng": 14.4378
    },
    "history": {
      "title": "Historical Overview",
      "content": "<p>The Duchy of Bohemia was established in the late 9th century under the Přemyslid dynasty, becoming a key kingdom within the Holy Roman Empire. Emperor Charles IV elevated Prague to an imperial capital in the 14th century, founding Charles University in 1348.</p><p>After centuries under Habsburg rule, Czechoslovakia was created in 1918 following WWI. After enduring Nazi occupation and Soviet domination during the Cold War, the peaceful 1989 Velvet Revolution ended communist rule, leading to the smooth 1993 Velvet Divorce into Czechia and Slovakia.</p>",
      "timeline": [
        {
          "year": "1348",
          "event": "Charles University founded in Prague."
        },
        {
          "year": "1415",
          "event": "Execution of Jan Hus sparks Hussite Wars."
        },
        {
          "year": "1918",
          "event": "Declaration of independent Czechoslovakia."
        },
        {
          "year": "1968",
          "event": "Prague Spring crushed by Warsaw Pact forces."
        },
        {
          "year": "1989",
          "event": "Velvet Revolution led by Václav Havel."
        },
        {
          "year": "2004",
          "event": "Czechia officially joins the European Union."
        }
      ]
    },
    "demographics": {
      "stats": {
        "population": "10.9 million",
        "gdp": "$330 billion",
        "capital": "Prague",
        "government": "Unitary Parliamentary Republic"
      },
      "content": "<p>Czechia features an advanced, export-driven high-income economy with a world-class automotive manufacturing sector (such as Škoda Auto), precision machinery, software development, and optics.</p><p>It maintains one of the lowest unemployment rates in the EU and boasts high living standards, excellent public healthcare, and historic industrial heritage.</p>"
    },
    "geography": {
      "stats": {
        "area": "78,866 km²",
        "continent": "Europe",
        "climate": "Temperate continental",
        "borders": "Germany, Austria, Slovakia, Poland"
      },
      "content": "<p>Landlocked in Central Europe, Czechia comprises the historic regions of Bohemia, Moravia, and Czech Silesia, bordered by natural mountain ranges like the Krkonoše and Bohemian Forest.</p><p>The landscape features rolling hills, lush river valleys of the Elbe and Vltava, and famed thermal mineral spring towns like Karlovy Vary.</p>"
    },
    "culture": {
      "languages": [
        "Czech"
      ],
      "currency": "Czech Koruna (CZK)",
      "content": "<p>Czech culture has given the world seminal literary masters like Franz Kafka and Karel Čapek (who coined the word \"robot\"), classical composers Antonín Dvořák and Bedřich Smetana, and world-famous Pilsner brewing tradition.</p><p>Prague's historic center is a UNESCO World Heritage site celebrated for intact Gothic, Renaissance, and Baroque architectural treasures.</p>",
      "highlights": [
        "Prague Castle & Charles Bridge",
        "Český Krumlov",
        "Karlovy Vary Spa Town",
        "Pilsner Urquell Brewery",
        "Kutná Hora Bone Church"
      ]
    }
  },
